/*高仿微信by板栗饼 源代码ee 整理喵个弥 禁二改二传（做适配OK）*/
/* 左下角菜单栏按钮的位置会受浏览器或手机的影响，按照我给的标注调整数值即可，顶栏高度调整同理，在线状态隐藏了但可以点击，实在想要也可以改成不隐藏 */
:root {
 /* 模拟手机屏幕的宽度和高度 */
 --screen-width: 350px;
 --screen-height: 650px;

 /* 背景色: 用于卡片、弹窗等 */
 --secondary-bg: #ffffff;

 /* 边框颜色: 用于分割线 */
 --border-color: #e0e0e0;

 /* 主要文字颜色: 用于标题和正文 */
 --text-primary: #1f1f1f;

 /* 次要文字颜色: 用于提示和时间戳 */
 --text-secondary: #8a8a8a;

 /* 主题强调色: 用于可交互元素 */
 --accent-color: #1f1f1f;

 /* --- 可调节项 --- */
 /* 在这里修改数值来调整顶部栏的高度 */
 --header-height: 20px;  /* 如果是330可以调到50左右 */
 /* 在这里修改数值来调整顶部栏文字的上下位置 (数值越大，文字越往下) */
 --header-text-padding-top: 7px; 
}

/* B. 顶部与底部栏 */
/* --- 1. 聊天界面顶部导航栏 --- */
#chat-interface-screen .header {
 /* 顶部背景颜色 */
 background-image: none !important;
 background-color: #ededed !important;

 /* 调节高度 */
 height: var(--header-height) !important;

 /* 中间标题文字颜色 */
 color: var(--text-primary) !important;
}

#chat-header-title-wrapper {
    padding-top: var(--header-text-padding-top) !important;
}

 /* 顶部分割线 */
 #chat-interface-screen .header {
    border-bottom: 0.5px solid rgba(0, 0, 0, 0.15) !important;
}
/* --- 2. 聊天界面底部输入区域 --- */
#chat-input-area {
 /* 底部背景颜色 */
 background-image: none !important;
 background-color: #f6f6f6 !important;
 }
/* 底部栏分割线 */
#chat-input-area {
    border-top: 0.5px solid rgba(0, 0, 0, 0.15) !important;
}
/* 自定义在线状态（想显示状态就把这里到下面那个}删掉) */
/* --- 1. “在线”状态 --- */
/* 隐藏在线状态，保留点击功能 */
#chat-header-status {
    opacity: 0 !important;
    pointer-events: auto !important; /* 确保隐藏后依然可以点击 */
}

/* C. 聊天内容区 */

/* --- 1. 消息整体布局与时间戳 --- */
/* 聊天中的日期时间戳 */
.date-stamp-bubble {
    background-color: rgba(255, 255, 255, 0.6) !important; /* 微透明白色背景 */
    color: black !important; /* 黑色文字 */
    border-radius: 4px !important; /* 更方的圆角 */
}

/* 拍一拍/系统提示样式 */
.message-bubble.system-bubble {
    background-color: rgba(255, 255, 255, 0.6) !important; /* 微透明白色背景 */
    color: black !important; /* 黑色文字 */
    border-radius: 4px !important; /* 更方的圆角 */
}
/* --- 输入框宽度修复与优化 --- */

/* 1. 让输入框的父容器表现为一个弹性盒子 */
#chat-input-main-row {
    display: flex;
    align-items: flex-end; /* 让输入框和按钮底部对齐，更美观 */
    gap: 0px; /* 输入框和按钮之间的间距 */
}
/* --- 输入框圆角 --- */
#chat-input {
    border-radius: 5px !important; 
}
/* 2. 移除固定宽度，让输入框自由生长 */
#chat-input {
    width: auto !important; 
    flex-grow: 1; /* 核心：让输入框占据所有剩余空间 */
    min-width: 0; /* 修复一些边缘情况下flex布局的溢出问题 */
}

/* 3. 确保按钮容器不会被挤压 */
#input-actions-wrapper {
    flex-shrink:0;
}

/* --- 输入框【被点击后】的样式 --- */
#chat-input:focus {
 outline: none !important;
 border-color: rgba(255, 255, 255, 0.5) !important;
}

/* --- 输入框里的提示文字样式 (隐藏) --- */
#chat-input::placeholder {
 color: transparent !important;
