/* === 特殊消息类型豁免规则 === */
/* 隐藏特殊消息的小尾巴和装饰 */
.message-bubble.is-transfer .content::before,
.message-bubble.is-waimai-request .content::before,
.message-bubble.is-red-packet .content::before,
.message-bubble.is-poll .content::before,
.message-bubble.is-link-share .content::before,
.message-bubble.is-sticker .content::before,
.message-bubble.system-bubble .content::before,
.message-bubble.is-transfer .content::after,
.message-bubble.is-waimai-request .content::after,
.message-bubble.is-red-packet .content::after,
.message-bubble.is-poll .content::after,
.message-bubble.is-link-share .content::after,
.message-bubble.is-sticker .content::after,
.message-bubble.system-bubble .content::after {
content: none !important;
}
/* 恢复特殊消息的原始样式 */
.message-bubble.is-transfer .content,
.message-bubble.is-waimai-request .content,
.message-bubble.is-red-packet .content,
.message-bubble.is-poll .content,
.message-bubble.is-link-share .content,
.message-bubble.is-sticker .content,
.message-bubble.system-bubble .content {
border-radius: 0 !important;
background: none !important;
border: none !important;
}
/* 图片消息豁免 */
.message-bubble .content:has(>img) {
background: none !important;
border-radius: 0 !important;
box-shadow: none !important;
border: none !important;
}
.message-bubble .content:has(>img)::before,
.message-bubble .content:has(>img)::after {
content: none !important;
}
.message-bubble:has(.content>img)::before {
display: none !important;
}
/* orange消息豁免 */
.message-bubble .content:has(>orange) {
padding:0!important;
border:none!important;
background:none!important;
box-shadow: none !important;
}
.message-bubble:has(.content>orange) {
filter: none !important;
}
.message-bubble:has(.content>orange)::before,
.message-bubble:has(.content>orange)::after {
display:none !important;
}
.message-bubble:has(.content>orange) .content::before,
.message-bubble:has(.content>orange) .content::after {
content: none !important;
}
