position: absolute;
top: calc(100% + 6px);
left: 0;
min-width: 100%;
max-width: 200%;
width: -moz-max-content;
width: max-content;
max-width: min(200%, 90vw);
height: auto;
max-height: 100%;
overflow-y: auto;
white-space: normal;
display: none;
z-index: 1;
}
.message-bubble.user .voice-transcript {
left: auto;
right: 0;
