}
.voice-transcript[style*="display: block"],
.voice-transcript.show,
.voice-transcript.active {
display: block;
}
.message-bubble:has(.voice-transcript[style*="display: block"]) {
margin-bottom: 42px;
}
.voice-transcript::-webkit-scrollbar {
display: none !important;
width: 0 !important;
height: 0 !important;
}
