/* 输入框引用框 */
#reply-preview-bar {
display: none !important;
opacity: 0 !important;
pointer-events: none !important;
visibility: hidden !important;
padding: 3px 4px;
margin: 0px 20px 3px 23px;
background-color: rgba(200, 200, 200, 0.3) !important;
border: none !important;
border-radius: 2px !important;
position: relative;
font-size: 13px;
color: #999999 !important;
backdrop-filter: none !important;
text-align: left !important;
max-width: calc(100% - 80px);
box-sizing: border-box;
order: 1;
white-space: nowrap !important;
overflow: hidden !important;
text-overflow: ellipsis !important;
display: flex;
align-items: center !important;
justify-content: flex-start !important;
}
/* 显示状态（当用户引用消息时） */
#reply-preview-bar[style*="display: block"],
#reply-preview-bar.show,
#reply-preview-bar.active {
display: flex !important;
opacity: 1 !important;
pointer-events: auto !important;
visibility: visible !important;
}
/* 内部文字样式保持 */
#reply-preview-bar * {
white-space: nowrap !important;
display: inline !important;
color: #999999 !important;
}
/* === 引用栏出现时上移 / 隐藏时恢复 === */
/* 默认状态：靠底 */
#chat-input-actions-top {
bottom: 5px !important;
transition: bottom 0.3s ease !important;
}
/* 引用栏显示时上移 */
#reply-preview-bar[style*="display: block"] ~ #chat-input-actions-top,
#reply-preview-bar.show ~ #chat-input-actions-top,
#reply-preview-bar.active ~ #chat-input-actions-top {
bottom: 36px !important; /* 这个高度根据引用栏高度可微调 */
}
/* === 特殊消息类型豁免规则 === */
/* 隐藏特殊消息的小尾巴和装饰 */
.message-bubble.is-transfer .content::before,
.message-bubble.is-waimai-request .content::before,
.message-bubble.is-red-packet .content::before,
.message-bubble.is-poll .content::before,
.message-bubble.is-link-share .content::before,
.message-bubble.is-sticker .content::before,
.message-bubble.system-bubble .content::before,
.message-bubble.is-transfer .content::after,
.message-bubble.is-waimai-request .content::after,
.message-bubble.is-red-packet .content::after,
.message-bubble.is-poll .content::after,
.message-bubble.is-link-share .content::after,
.message-bubble.is-sticker .content::after,
.message-bubble.system-bubble .content::after {
content: none !important;
}
/* 恢复特殊消息的原始样式 */
.message-bubble.is-transfer .content,
.message-bubble.is-waimai-request .content,
.message-bubble.is-red-packet .content,
.message-bubble.is-poll .content,
.message-bubble.is-link-share .content,
.message-bubble.is-sticker .content,
.message-bubble.system-bubble .content {
border-radius: 0 !important;
background: none !important;
border: none !important;
}
/* 图片消息豁免 */
.message-bubble .content:has(>img) {
background: none !important;
border-radius: 0 !important;
box-shadow: none !important;
